package com.immersio.scenarios.domain; import jakarta.persistence.*; import java.math.BigDecimal; import java.util.UUID;
@Entity @Table(name="\"ScenarioItems\"") public class ScenarioItem { @Id @GeneratedValue(strategy=GenerationType.UUID) @Column(name="\"Id\"") private UUID id; @Column(name="\"ScenarioId\"",insertable=false,updatable=false) private UUID scenarioId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="\"ScenarioId\"") private Scenario scenario; @Column(name="\"Name\"") private String name; @Column(name="\"Price\"") private BigDecimal price=BigDecimal.ZERO; @Column(name="\"ImageUrl\"") private String imageUrl; @Column(name="\"Icon\"") private String icon; protected ScenarioItem(){} public ScenarioItem(Scenario s,String n,BigDecimal p,String i,String icon){scenario=s;name=n;price=p;imageUrl=i;this.icon=icon;} public UUID getId(){return id;} public UUID getScenarioId(){return scenarioId;} public String getName(){return name;} public BigDecimal getPrice(){return price;} public String getImageUrl(){return imageUrl;} public String getIcon(){return icon;} }
